#[test]
fn health_probe_accepts_healthy_loopback_and_rejects_wildcard_identity() {
    let listener = TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).expect("health listener");
    let address = listener.local_addr().expect("health address");
    let worker = thread::spawn(move || {
        let (mut stream, _) = listener.accept().expect("health accept");
        let mut request = [0_u8; 256];
        let _ = stream.read(&mut request).expect("health read");
        stream
            .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nOK")
            .expect("health response");
    });
    assert!(endpoint_is_healthy(&format!(
        "http://127.0.0.1:{}",
        address.port()
    )));
    worker.join().expect("health worker");
    assert!(!endpoint_is_healthy(&format!(
        "http://0.0.0.0:{}",
        address.port()
    )));
}

#[test]
fn crashed_or_stale_process_state_is_not_reported_resident() {
    let root = temp_root("stale-process");
    let manager = ManagedLocalRuntime::open(root.clone()).expect("manager");
    let port = reserve_loopback_port().expect("unused loopback port");
    let config = ManagedLocalModelConfig {
        state_root: root.clone(),
        environment: ManagedExecutionEnvironment::WindowsNative,
        model_id: "gguf:test".to_owned(),
        model_content_sha256: "a".repeat(64),
        model_path: root.join("model.gguf"),
        model_size_bytes: 1,
        quantization: None,
        runtime_tag: PINNED_LLAMA_CPP_TAG.to_owned(),
        runtime_revision: PINNED_LLAMA_CPP_REVISION.to_owned(),
        runtime_artifact_sha256: "b".repeat(64),
        runtime_compatibility_version: MANAGED_RUNTIME_COMPATIBILITY_VERSION.to_owned(),
    };
    manager
        .write_process_state(&ManagedProcessState {
            schema_version: STATE_SCHEMA_VERSION,
            environment: ManagedExecutionEnvironment::WindowsNative,
            process_id: u32::MAX,
            endpoint: format!("http://127.0.0.1:{port}"),
            runtime_revision: PINNED_LLAMA_CPP_REVISION.to_owned(),
            model_content_sha256: config.model_content_sha256.clone(),
            started_unix_ms: now_unix_ms(),
        })
        .expect("stale process state");
    assert!(!ManagedLocalRuntime::is_resident(&config).expect("residency"));
    let _ = fs::remove_dir_all(root);
}

#[test]
fn startup_diagnostics_separate_gpu_capability_and_resource_failures() {
    let root = temp_root("startup-diagnostics");
    let manager = ManagedLocalRuntime::open(root.clone()).expect("manager");
    let log = manager.log_path(ManagedExecutionEnvironment::WindowsNative);
    fs::create_dir_all(log.parent().expect("log parent")).expect("log directory");
    fs::write(&log, "Vulkan device not found: failed to initialize GPU").expect("gpu log");
    let gpu = manager.classify_startup_failure(
        ManagedExecutionEnvironment::WindowsNative,
        "startup failed".to_owned(),
    );
    assert_eq!(gpu.layer(), ManagedDiagnosticLayer::GpuOrBackendCapability);
    fs::write(&log, "failed to allocate buffer: out of memory").expect("oom log");
    let resource = manager.classify_startup_failure(
        ManagedExecutionEnvironment::WindowsNative,
        "startup failed".to_owned(),
    );
    assert_eq!(resource.layer(), ManagedDiagnosticLayer::ModelResource);
    let _ = fs::remove_dir_all(root);
}

#[test]
fn benchmark_runtime_identity_includes_revision_environment_and_artifact_digest() {
    let config = ManagedLocalModelConfig {
        state_root: PathBuf::from("state"),
        environment: ManagedExecutionEnvironment::WindowsNative,
        model_id: "gguf:test".to_owned(),
        model_content_sha256: "a".repeat(64),
        model_path: PathBuf::from("model.gguf"),
        model_size_bytes: 1,
        quantization: Some("Q4_K_M".to_owned()),
        runtime_tag: PINNED_LLAMA_CPP_TAG.to_owned(),
        runtime_revision: PINNED_LLAMA_CPP_REVISION.to_owned(),
        runtime_artifact_sha256: "b".repeat(64),
        runtime_compatibility_version: MANAGED_RUNTIME_COMPATIBILITY_VERSION.to_owned(),
    };
    let identity = config.benchmark_runtime_identity();
    assert!(identity.contains(PINNED_LLAMA_CPP_REVISION));
    assert!(identity.contains("env=windows_native"));
    assert!(identity.contains(&"b".repeat(64)));
}

